/**
 * @distilled.cloud/proxmox-backup — Proxmox Backup Server API SDK for
 * Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy
 * models in `.generated-specs` (written by `scripts/convert.ts` from PBS's
 * own `apidoc.js`, mirrored under `specs/`). Everything else in this
 * folder is hand-written.
 *
 * One module per PBS top-level path segment — `access`, `admin`, `backup`,
 * `config`, `nodes`, `ping`, `pull`, `push`, `reader`, `root`, `status`,
 * `tape`, `version` — the same split the vendor's own api-viewer uses
 * (measured on the pinned schema; see `scripts/convert.ts`'s header for
 * per-bucket endpoint counts).
 *
 * @example
 * ```ts
 * import * as ProxmoxBackup from "@distilled.cloud/proxmox-backup";
 *
 * const status = yield* ProxmoxBackup.Services.nodes.getNodeTaskStatus({
 *   node: "pbs1",
 *   upid: "UPID:pbs1:00001234:...",
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ProxmoxBackupProtocol,
  type ProxmoxBackupOpError,
  type ProxmoxBackupOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
